from control import *
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares

def tf(R=np.eye(3),p=np.zeros(3)):
 T=np.eye(4);T[:3,:3]=R;T[:3,3]=p;return T
def fk(q):
 T=np.eye(4)
 for qi,a,d,al in zip(q,[0,0,0,.0825,-.0825,0,.088],[.333,0,.316,0,.384,0,0],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
  T=T@tf(Rot.from_rotvec([al,0,0]).as_matrix(),[a,0,0])@tf(Rot.from_rotvec([0,0,qi]).as_matrix(),[0,0,d])
 return T@tf(Rot.from_rotvec([0,0,-np.pi/4]).as_matrix(),[0,0,.2104])
def base(o=None):
 o=latest() if o is None else o;p=state(o);F=fk(p[4:11]);R=Rot.from_euler('z',np.pi/2+p[2]).as_matrix();return tf(R,p[26:29]-R@F[:3,3])
def pose(o=None):
 o=latest() if o is None else o
 return base(o)@fk(state(o)[4:11])
def xyz(cam,u,v,o=None):
 o=latest() if o is None else o
 c=o.meta['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);D=o.depth[cam];D=D[-1] if D.ndim==3 else D
 z=float(D[int(v),int(u)]);p=np.linalg.inv(K)@np.array([u,v,1])*z;p*=np.array([1,-1,-1]);return (T@np.r_[p,1])[:3]
def solve(pos,rot=None,o=None):
 o=latest() if o is None else o;p=state(o);B=base(o);rot=pose(o)[:3,:3] if rot is None else rot
 def err(q):
  T=B@fk(q);return np.r_[(T[:3,3]-pos)*4,Rot.from_matrix(rot@T[:3,:3].T).as_rotvec(),.015*(q-p[4:11])]
 sol=least_squares(err,p[4:11],bounds=([-2.89,-1.76,-2.89,-3.07,-2.89,-.017,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=200)
 print('IK',sol.x,'error',err(sol.x)[:6]);return sol.x

def move(pos,rot=None,grip=None,steps=40,name='cart'):
 return act(q=solve(np.array(pos),rot),grip=grip,steps=steps,name=name)
